// Permanent Embedded Audio Data (Offline, Local, Zero Network Overhead)

function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = typeof window !== 'undefined' ? window.atob(base64) : '';
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export const WIN_ATS_B64 = "";
export const WIN_SMALL_TALL_B64 = "";

let cachedAtsBlobUrl: string | null = null;
let cachedSmallTallBlobUrl: string | null = null;

let cachedAtsBytes: Uint8Array | null = null;
let cachedSmallTallBytes: Uint8Array | null = null;

export function getAtsBytes(): Uint8Array {
  if (!cachedAtsBytes && typeof window !== 'undefined') {
    cachedAtsBytes = base64ToUint8Array(WIN_ATS_B64);
  }
  return cachedAtsBytes || new Uint8Array(0);
}

export function getSmallTallBytes(): Uint8Array {
  if (!cachedSmallTallBytes && typeof window !== 'undefined') {
    cachedSmallTallBytes = base64ToUint8Array(WIN_SMALL_TALL_B64);
  }
  return cachedSmallTallBytes || new Uint8Array(0);
}

export function getAtsBlobUrl(): string {
  if (!cachedAtsBlobUrl && typeof window !== 'undefined') {
    try {
      const bytes = getAtsBytes();
      const blob = new Blob([bytes], { type: 'audio/mp3' });
      cachedAtsBlobUrl = URL.createObjectURL(blob);
    } catch (e) {
      console.warn('Failed to create ATS Blob URL:', e);
      cachedAtsBlobUrl = '/win_ats.mp3';
    }
  }
  return cachedAtsBlobUrl || '/win_ats.mp3';
}

export function getSmallTallBlobUrl(): string {
  if (!cachedSmallTallBlobUrl && typeof window !== 'undefined') {
    try {
      const bytes = getSmallTallBytes();
      const blob = new Blob([bytes], { type: 'audio/mp3' });
      cachedSmallTallBlobUrl = URL.createObjectURL(blob);
    } catch (e) {
      console.warn('Failed to create Small/Tall Blob URL:', e);
      cachedSmallTallBlobUrl = '/win_small_tall.mp3';
    }
  }
  return cachedSmallTallBlobUrl || '/win_small_tall.mp3';
}
